<script setup lang="ts">
import { ArrowRight, Baby, Cross, HeartPulse, Leaf, PackageCheck, ShieldCheck, Sparkles, Truck } from '@lucide/vue'
import type { StorefrontPayload } from '#shared/types/storefront'
import PharmacyProductCard from '../components/PharmacyProductCard.vue'
const props = defineProps<{ storefront: StorefrontPayload }>()
const { activeCategories, productImage, usePlaceholder } = useStorefrontCatalog(props.storefront)
const featured = computed(() => (props.storefront.products.some(item => item.is_featured) ? props.storefront.products.filter(item => item.is_featured) : props.storefront.products).slice(0,8))
const heroProduct = computed(() => featured.value.find(item => productImage(item)) || featured.value[0])
const theme = computed(() => props.storefront.site.theme)
const heroTitle = computed(() => theme.value?.hero_title || 'Cuidado que cabe na sua rotina.')
const heroSubtitle = computed(() => theme.value?.hero_subtitle || 'Encontre o que precisa com clareza, confiança e entrega para a sua região.')
const heroImage = computed(() => theme.value?.hero_image_url || productImage(heroProduct.value))
const categoryIcons = [HeartPulse, Sparkles, Baby, Leaf, Cross, ShieldCheck]
</script>

<template>
  <main>
    <section class="hero"><div class="hero-copy"><span class="eyebrow"><i>+</i> Cuidado simples, todos os dias</span><h1>{{ heroTitle }}</h1><p>{{ heroSubtitle }}</p><div class="hero-actions"><NuxtLink to="/produtos">Ver produtos <ArrowRight :size="18"/></NuxtLink><NuxtLink to="/categorias" class="secondary">Explorar cuidados</NuxtLink></div><div class="hero-proof"><span><ShieldCheck :size="17"/>Compra protegida</span><span><Truck :size="17"/>Entrega calculada pelo CEP</span></div></div><div class="care-card"><div class="blister-dots" aria-hidden="true"><i v-for="n in 12" :key="n"></i></div><div class="hero-product"><img v-if="heroImage" :src="heroImage" :alt="heroProduct?.name || storefront.site.name" fetchpriority="high" @error="usePlaceholder"><div v-else class="hero-placeholder">+</div></div><div v-if="heroProduct" class="hero-label"><span>Destaque de hoje</span><strong>{{ heroProduct.name }}</strong><NuxtLink :to="`/produto/${heroProduct.slug}`" aria-label="Ver produto"><ArrowRight :size="18"/></NuxtLink></div></div></section>

    <section class="service-strip"><div><Truck/><span><strong>Entrega conveniente</strong><small>Prazo para a sua região</small></span></div><div><ShieldCheck/><span><strong>Compra segura</strong><small>Dados sempre protegidos</small></span></div><div><PackageCheck/><span><strong>Pedido acompanhado</strong><small>Do preparo à entrega</small></span></div></section>

    <section class="section categories-section"><div class="section-heading"><div><span>Cuidados por rotina</span><h2>Encontre do seu jeito.</h2></div><NuxtLink to="/categorias">Ver todas <ArrowRight :size="17"/></NuxtLink></div><div v-if="activeCategories.length" class="category-grid"><NuxtLink v-for="(category,index) in activeCategories.slice(0,6)" :key="category.id" :to="`/categoria/${category.slug}`"><component :is="categoryIcons[index % categoryIcons.length]" :size="25"/><span>{{ category.name }}</span><small>{{ category.description || 'Produtos para cuidar da sua rotina.' }}</small><ArrowRight class="category-arrow" :size="17"/></NuxtLink></div><div v-else class="empty">As categorias estão sendo organizadas.</div></section>

    <section class="section products-section"><div class="section-heading"><div><span>Escolhas da farmácia</span><h2>{{ theme?.featured_title || 'Para ter sempre por perto.' }}</h2></div><NuxtLink to="/produtos">Ver tudo <ArrowRight :size="17"/></NuxtLink></div><div v-if="featured.length" class="product-grid"><PharmacyProductCard v-for="product in featured" :key="product.id" :product="product" :storefront="storefront"/></div><div v-else class="empty">A seleção de produtos estará disponível em breve.</div></section>

    <section class="guidance"><div><span>Orientação importa</span><h2>Informação clara também é cuidado.</h2><p>Leia as instruções dos produtos e, em caso de dúvidas, procure sempre um profissional de saúde.</p><NuxtLink to="/produtos">Consultar produtos <ArrowRight :size="17"/></NuxtLink></div><aside><div class="mini-cross">+</div><strong>Use medicamentos com responsabilidade.</strong><small>Não interrompa tratamentos sem orientação médica.</small></aside></section>

